impl ::flatbuffers::Verifiable for FCK<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<u64>("SELF_OFFSET", Self::VT_SELF_OFFSET, false)?
            .visit_field::<u64>("PREVIOUS", Self::VT_PREVIOUS, false)?
            .visit_field::<u32>("FEED_ID", Self::VT_FEED_ID, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("TYPE", Self::VT_TYPE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("PROVIDER", Self::VT_PROVIDER, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("SOURCE", Self::VT_SOURCE, false)?
            .visit_field::<u32>("GENERATION", Self::VT_GENERATION, false)?
            .visit_field::<i64>("COMMITTED_AT", Self::VT_COMMITTED_AT, false)?
            .visit_field::<u64>("APPLIED_THROUGH", Self::VT_APPLIED_THROUGH, false)?
            .visit_field::<u64>("TYPE_SEQ_HIGH", Self::VT_TYPE_SEQ_HIGH, false)?
            .visit_field::<FCKCounters>("COUNTERS", Self::VT_COUNTERS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, FCKSegment>>>("SEGMENTS", Self::VT_SEGMENTS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, u8>>>("SEGMENT_DIGESTS", Self::VT_SEGMENT_DIGESTS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, u8>>>("COMMITS_ROOT_CID", Self::VT_COMMITS_ROOT_CID, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, u8>>>("PREVIOUS_FEED_ROOT_CID", Self::VT_PREVIOUS_FEED_ROOT_CID, false)?
            .finish();
        Ok(())
    }
}

