pub struct FCKBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> FCKBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_SELF_OFFSET(&mut self, SELF_OFFSET: u64) {
        self.fbb_.push_slot::<u64>(FCK::VT_SELF_OFFSET, SELF_OFFSET, 0);
    }

    #[inline]
    pub fn add_PREVIOUS(&mut self, PREVIOUS: u64) {
        self.fbb_.push_slot::<u64>(FCK::VT_PREVIOUS, PREVIOUS, 0);
    }

    #[inline]
    pub fn add_FEED_ID(&mut self, FEED_ID: u32) {
        self.fbb_.push_slot::<u32>(FCK::VT_FEED_ID, FEED_ID, 0);
    }

    #[inline]
    pub fn add_TYPE(&mut self, TYPE: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(FCK::VT_TYPE, TYPE);
    }

    #[inline]
    pub fn add_PROVIDER(&mut self, PROVIDER: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(FCK::VT_PROVIDER, PROVIDER);
    }

    #[inline]
    pub fn add_SOURCE(&mut self, SOURCE: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(FCK::VT_SOURCE, SOURCE);
    }

    #[inline]
    pub fn add_GENERATION(&mut self, GENERATION: u32) {
        self.fbb_.push_slot::<u32>(FCK::VT_GENERATION, GENERATION, 0);
    }

    #[inline]
    pub fn add_COMMITTED_AT(&mut self, COMMITTED_AT: i64) {
        self.fbb_.push_slot::<i64>(FCK::VT_COMMITTED_AT, COMMITTED_AT, 0);
    }

    #[inline]
    pub fn add_APPLIED_THROUGH(&mut self, APPLIED_THROUGH: u64) {
        self.fbb_.push_slot::<u64>(FCK::VT_APPLIED_THROUGH, APPLIED_THROUGH, 0);
    }

    #[inline]
    pub fn add_TYPE_SEQ_HIGH(&mut self, TYPE_SEQ_HIGH: u64) {
        self.fbb_.push_slot::<u64>(FCK::VT_TYPE_SEQ_HIGH, TYPE_SEQ_HIGH, 0);
    }

    #[inline]
    pub fn add_COUNTERS(&mut self, COUNTERS: &FCKCounters) {
        self.fbb_.push_slot_always::<&FCKCounters>(FCK::VT_COUNTERS, COUNTERS);
    }

    #[inline]
    pub fn add_SEGMENTS(&mut self, SEGMENTS: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , FCKSegment>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(FCK::VT_SEGMENTS, SEGMENTS);
    }

    #[inline]
    pub fn add_SEGMENT_DIGESTS(&mut self, SEGMENT_DIGESTS: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , u8>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(FCK::VT_SEGMENT_DIGESTS, SEGMENT_DIGESTS);
    }

    #[inline]
    pub fn add_COMMITS_ROOT_CID(&mut self, COMMITS_ROOT_CID: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , u8>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(FCK::VT_COMMITS_ROOT_CID, COMMITS_ROOT_CID);
    }

    #[inline]
    pub fn add_PREVIOUS_FEED_ROOT_CID(&mut self, PREVIOUS_FEED_ROOT_CID: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , u8>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(FCK::VT_PREVIOUS_FEED_ROOT_CID, PREVIOUS_FEED_ROOT_CID);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> FCKBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        FCKBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<FCK<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

impl ::core::fmt::Debug for FCK<'_> {
    fn fmt(&self, f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
        let mut ds = f.debug_struct("FCK");
        ds.field("SELF_OFFSET", &self.SELF_OFFSET());
        ds.field("PREVIOUS", &self.PREVIOUS());
        ds.field("FEED_ID", &self.FEED_ID());
        ds.field("TYPE", &self.TYPE());
        ds.field("PROVIDER", &self.PROVIDER());
        ds.field("SOURCE", &self.SOURCE());
        ds.field("GENERATION", &self.GENERATION());
        ds.field("COMMITTED_AT", &self.COMMITTED_AT());
        ds.field("APPLIED_THROUGH", &self.APPLIED_THROUGH());
        ds.field("TYPE_SEQ_HIGH", &self.TYPE_SEQ_HIGH());
        ds.field("COUNTERS", &self.COUNTERS());
        ds.field("SEGMENTS", &self.SEGMENTS());
        ds.field("SEGMENT_DIGESTS", &self.SEGMENT_DIGESTS());
        ds.field("COMMITS_ROOT_CID", &self.COMMITS_ROOT_CID());
        ds.field("PREVIOUS_FEED_ROOT_CID", &self.PREVIOUS_FEED_ROOT_CID());
        ds.finish()
    }
}

#[non_exhaustive]
#[derive(Debug, Clone, PartialEq)]
pub struct FCKT {
    pub SELF_OFFSET: u64,
    pub PREVIOUS: u64,
    pub FEED_ID: u32,
    pub TYPE: Option<alloc::string::String>,
    pub PROVIDER: Option<alloc::string::String>,
    pub SOURCE: Option<alloc::string::String>,
    pub GENERATION: u32,
    pub COMMITTED_AT: i64,
    pub APPLIED_THROUGH: u64,
    pub TYPE_SEQ_HIGH: u64,
    pub COUNTERS: Option<FCKCountersT>,
    pub SEGMENTS: Option<alloc::vec::Vec<FCKSegmentT>>,
    pub SEGMENT_DIGESTS: Option<alloc::vec::Vec<u8>>,
    pub COMMITS_ROOT_CID: Option<alloc::vec::Vec<u8>>,
    pub PREVIOUS_FEED_ROOT_CID: Option<alloc::vec::Vec<u8>>,
}

impl Default for FCKT {
    fn default() -> Self {
        Self {
            SELF_OFFSET: 0,
            PREVIOUS: 0,
            FEED_ID: 0,
            TYPE: None,
            PROVIDER: None,
            SOURCE: None,
            GENERATION: 0,
            COMMITTED_AT: 0,
            APPLIED_THROUGH: 0,
            TYPE_SEQ_HIGH: 0,
            COUNTERS: None,
            SEGMENTS: None,
            SEGMENT_DIGESTS: None,
            COMMITS_ROOT_CID: None,
            PREVIOUS_FEED_ROOT_CID: None,
        }
    }
}

impl FCKT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<FCK<'b>> {
        let SELF_OFFSET = self.SELF_OFFSET;
        let PREVIOUS = self.PREVIOUS;
        let FEED_ID = self.FEED_ID;
        let TYPE = self.TYPE.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let PROVIDER = self.PROVIDER.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let SOURCE = self.SOURCE.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let GENERATION = self.GENERATION;
        let COMMITTED_AT = self.COMMITTED_AT;
        let APPLIED_THROUGH = self.APPLIED_THROUGH;
        let TYPE_SEQ_HIGH = self.TYPE_SEQ_HIGH;
        let COUNTERS_tmp = self.COUNTERS.as_ref().map(|x| x.pack());
        let COUNTERS = COUNTERS_tmp.as_ref();
        let SEGMENTS = self.SEGMENTS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack()).collect();_fbb.create_vector(&w)
        });
        let SEGMENT_DIGESTS = self.SEGMENT_DIGESTS.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let COMMITS_ROOT_CID = self.COMMITS_ROOT_CID.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let PREVIOUS_FEED_ROOT_CID = self.PREVIOUS_FEED_ROOT_CID.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        FCK::create(_fbb, &FCKArgs{
            SELF_OFFSET,
            PREVIOUS,
            FEED_ID,
            TYPE,
            PROVIDER,
            SOURCE,
            GENERATION,
            COMMITTED_AT,
            APPLIED_THROUGH,
            TYPE_SEQ_HIGH,
            COUNTERS,
            SEGMENTS,
            SEGMENT_DIGESTS,
            COMMITS_ROOT_CID,
            PREVIOUS_FEED_ROOT_CID,
        })
    }
}

/// Verifies that a buffer of bytes contains a `FCK`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_fck_unchecked`.
#[inline]
pub fn root_as_fck(buf: &[u8]) -> Result<FCK<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<FCK>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `FCK` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_fck_unchecked`.
#[inline]
pub fn size_prefixed_root_as_fck(buf: &[u8]) -> Result<FCK<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<FCK>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `FCK` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_fck_unchecked`.
#[inline]
pub fn root_as_fck_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<FCK<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<FCK<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `FCK` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_fck_unchecked`.
#[inline]
pub fn size_prefixed_root_as_fck_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<FCK<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<FCK<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a FCK and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `FCK`.
#[inline]
pub unsafe fn root_as_fck_unchecked(buf: &[u8]) -> FCK<'_> {
    unsafe { ::flatbuffers::root_unchecked::<FCK>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed FCK and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `FCK`.
#[inline]
pub unsafe fn size_prefixed_root_as_fck_unchecked(buf: &[u8]) -> FCK<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<FCK>(buf) }
}

pub const FCK_IDENTIFIER: &str = "$FCK";

#[inline]
pub fn fck_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, FCK_IDENTIFIER, false)
}

#[inline]
pub fn fck_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, FCK_IDENTIFIER, true)
}

#[inline]
pub fn finish_fck_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<FCK<'a>>
) {
    fbb.finish(root, Some(FCK_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_fck_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<FCK<'a>>
) {
    fbb.finish_size_prefixed(root, Some(FCK_IDENTIFIER));
}
